/* Módulo: js/admin-legacy.js | Función: lógica original del bloque 5 | Depende de: scripts anteriores en orden de carga | Expone: declaraciones y efectos globales originales, cuando corresponda. */

/* Panel extraído y adaptado al catálogo de comida. No incluye bot de transferencias. */
const PANEL_MODULES=[['history','Viajes realizados',UI.orders],['users','Usuarios y permisos',UI.business],['commissions','Comisiones y liquidaciones',UI.calc],['deliveries','Entregas y seguimiento',UI.map],['ticket','Diseño de ticket',UI.receipt],['customers','Clientes y bloqueos',UI.shield]];
adminTabs.push(...PANEL_MODULES);
let panelAccess={owner:false,modules:[]},panelEpoch=0,panelRouteReady=false,panelTripSerial=0;
const panelBasePane=renderAdminPane,panelBaseBusiness=renderBusinessAdmin,panelBaseTrip=renderTripAdmin;
const panelField=(id,label,value='',type='text')=>`<div class="field"><label for="${id}">${label}</label><input class="input" id="${id}" type="${type}" value="${esc(String(value??''))}"></div>`;
const panelButton=(id,label,icon=UI.save,cls='')=>`<button type="button" id="${id}" class="btn ${cls}">${icon}<span>${label}</span></button>`;
function panelCan(id){return !!adminSession&&(panelAccess.owner||panelAccess.modules.includes(id))}
async function panelCall(action,payload={}){if(!supabaseClient||!adminSession)throw Error('Inicia sesión como administrador.');const {data,error}=await supabaseClient.rpc('catalog_panel',{p_action:action,p_payload:payload});if(error)throw Error(error.message);return data}
async function panelVerify(){panelAccess={owner:false,modules:[]};if(!supabaseClient)return false;const {data,error}=await supabaseClient.auth.getUser();if(error||!data?.user)return false;try{panelAccess=await panelCall('access')}catch{const r=await supabaseClient.rpc('is_catalog_admin');panelAccess={owner:!r.error&&r.data===true,modules:[]}}if(!panelAccess.owner){try{const check=await supabaseClient.rpc('is_catalog_admin');if(!check.error&&check.data===true)panelAccess.owner=true}catch(e){console.warn('Verificación de administrador',e)}}return panelAccess.owner||panelAccess.modules.length>0}
openAdmin=async function(){if(adminSession&&await panelVerify()){renderAdmin();openModal('adminModal');return}const email=document.getElementById('adminEmailInput');if(email)email.value=localStorage.getItem('foodCatalogAdminEmail')||'';document.getElementById('adminPasswordInput').value='';openModal('pinModal')};
checkPin=async function(){const btn=document.getElementById('pinSubmit');btn.disabled=true;try{if(!supabaseClient)await initSupabase();const email=document.getElementById('adminEmailInput').value.trim(),password=document.getElementById('adminPasswordInput').value;const {data,error}=await supabaseClient.auth.signInWithPassword({email,password});if(error)throw error;adminSession=data.session;if(!await panelVerify()){await supabaseClient.auth.signOut();adminSession=null;throw Error('Esta cuenta no tiene permisos administrativos.')}localStorage.setItem('foodCatalogAdminEmail',email);closeModal('pinModal');renderAdmin();openModal('adminModal')}catch(e){toast(e.message,'error')}finally{btn.disabled=false}};
renderAdmin=function(){const tabs=adminTabs.filter(([id])=>panelCan(id));if(!tabs.some(([id])=>id===activeAdmin))activeAdmin=tabs[0]?.[0];document.getElementById('adminTabs').innerHTML=tabs.map(([id,label,ico])=>`<button class="tab-btn ${activeAdmin===id?'active':''}" data-tab="${id}">${ico}<span>${label}</span></button>`).join('');if(activeAdmin)renderAdminPane(activeAdmin)};
renderAdminPane=async function(id){if(!panelCan(id))return toast('No tienes acceso a este módulo.','error');activeAdmin=id;const epoch=++panelEpoch;document.querySelectorAll('.tab-btn').forEach(b=>b.classList.toggle('active',b.dataset.tab===id));const c=document.getElementById('adminContent');const functions={history:panelHistory,users:panelUsers,commissions:panelCommissions,deliveries:panelDeliveries,ticket:panelTicket,customers:panelCustomers};try{if(functions[id]){c.innerHTML='<p class="muted" role="status">Cargando…</p>';await functions[id](c,epoch)}else panelBasePane(id);if(epoch!==panelEpoch)return;const row=document.createElement('div');row.className='faithful-session';const who=document.createElement('span');who.className='small muted';who.textContent=(adminSession?.user?.email||'')+' · '+(panelAccess.owner?'Propietario':'Colaborador');const logout=document.createElement('button');logout.className='btn ghost';logout.innerHTML=UI.lock+'<span>Cerrar sesión</span>';logout.onclick=()=>adminSignOut();row.append(who,logout);c.prepend(row)}catch(e){if(epoch===panelEpoch)c.innerHTML=`<div class="section-card"><h3>${esc(adminTabs.find(t=>t[0]===id)?.[1]||id)}</h3><div class="notice">${esc(e.message)}</div>${panelButton('panelRetry','Volver a intentar',UI.refresh)}</div>`;document.getElementById('panelRetry')?.addEventListener('click',()=>renderAdminPane(id))}};
const panelLogout=adminSignOut;adminSignOut=async function(){panelAccess={owner:false,modules:[]};panelEpoch++;await panelLogout()};
async function panelRun(button,task,message){button.disabled=true;try{await task();if(message)toast(message,'ok')}catch(e){toast(e.message,'error')}finally{if(button.isConnected)button.disabled=false}}
renderBusinessAdmin=function(c){panelBaseBusiness(c);const logo=document.getElementById('bizLogo');logo.accept='image/png,image/jpeg,image/webp';const preview=document.createElement('div');preview.className='faithful-logo-preview';preview.innerHTML=(state.config.logo?`<img src="${esc(state.config.logo)}" alt="Logo del negocio">`:'')+panelButton('panelDeleteLogo','Quitar logo',UI.trash,'ghost');logo.after(preview);document.getElementById('panelDeleteLogo').onclick=()=>{state.config.logo='';save();renderHeader();renderBusinessAdmin(c)};logo.onchange=async()=>{try{if(logo.files[0])state.config.logo=await panelReadImage(logo.files[0]);save();renderHeader();renderBusinessAdmin(c)}catch(e){toast(e.message,'error')}};const pay=document.getElementById('paymentAdmin');pay.innerHTML=state.config.payments.map(p=>`<div class="section-card"><div class="admin-grid two">${panelField('pt_'+p.id,'Nombre',p.title)}${panelField('pd_'+p.id,'Cuenta / CLABE / instrucciones',p.data)}${panelField('pb_'+p.id,'Beneficiario',p.beneficiary)}</div><label class="row"><input type="checkbox" data-panel-visible="${esc(p.id)}" ${p.visible!==false?'checked':''}>Mostrar al cliente</label><button class="icon-btn" data-panel-delete="${esc(p.id)}" aria-label="Eliminar método">${UI.trash}</button></div>`).join('');pay.querySelectorAll('[data-panel-delete]').forEach(b=>b.onclick=()=>{if(confirm('¿Eliminar este método de pago?')){state.config.payments=state.config.payments.filter(p=>p.id!==b.dataset.panelDelete);save();renderBusinessAdmin(c)}});document.getElementById('addPayment').onclick=()=>{state.config.payments.push({id:uid('pay'),title:'Nuevo método',data:'',beneficiary:'',visible:true});renderBusinessAdmin(c)};document.getElementById('savePayments').onclick=e=>panelRun(e.currentTarget,async()=>{const copy=state.config.payments.map(p=>({...p,title:document.getElementById('pt_'+p.id).value.trim(),data:document.getElementById('pd_'+p.id).value.trim(),beneficiary:document.getElementById('pb_'+p.id).value.trim(),visible:pay.querySelector(`[data-panel-visible="${p.id}"]`).checked}));if(copy.some(p=>!p.title))throw Error('Escribe el nombre de cada método.');state.config.payments=copy;saveLocal();clearTimeout(cloudSyncTimer);await syncAdminStateToCloud()},'Métodos guardados.');document.getElementById('saveIdentity').onclick=e=>panelRun(e.currentTarget,async()=>{const name=document.getElementById('bizName').value.trim();if(!name)throw Error('Escribe el nombre del negocio.');state.config.businessName=name;state.config.tagline=document.getElementById('bizTagline').value.trim();saveLocal();renderHeader();clearTimeout(cloudSyncTimer);await syncAdminStateToCloud()},'Identidad guardada.')};
async function panelReadImage(file){if(file.size>5*1024*1024)throw Error('Máximo 5 MB.');const b=await createImageBitmap(file);try{if(b.width*b.height>24000000)throw Error('Máximo 24 megapíxeles.');const canvas=document.createElement('canvas'),scale=Math.min(1,800/Math.max(b.width,b.height));canvas.width=Math.max(1,Math.round(b.width*scale));canvas.height=Math.max(1,Math.round(b.height*scale));canvas.getContext('2d').drawImage(b,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/png')}finally{b.close()}}
const panelBaseCart=renderCart;renderCart=function(){const payments=state.config.payments;try{state.config.payments=payments.filter(p=>p.visible!==false).map(p=>({...p,data:p.data+(p.beneficiary?' · Beneficiario: '+p.beneficiary:'')}));panelBaseCart()}finally{state.config.payments=payments}};
setTripDestination=async function(lat,lng){if(!tripMap)return;panelRouteReady=false;const serial=++panelTripSerial;const map=tripMap;if(tripDestMarker)tripDestMarker.setLatLng([lat,lng]);else{tripDestMarker=L.marker([lat,lng],{draggable:true}).addTo(map);tripDestMarker.on('dragend',e=>{const ll=e.target.getLatLng();setTripDestination(ll.lat,ll.lng)})}try{const o=state.config.origin,res=await routeDistance(o.lat,o.lng,lat,lng);if(serial!==panelTripSerial||map!==tripMap||activeAdmin!=='trip')return;tripKm=res.km;if(tripRouteLayer){map.removeLayer(tripRouteLayer);tripRouteLayer=null}if(res.geo){tripRouteLayer=L.geoJSON(res.geo).addTo(map);map.fitBounds(tripRouteLayer.getBounds(),{padding:[20,20]})}panelRouteReady=Number.isFinite(tripKm)&&tripKm>0;recalcTrip();if(res.fallback)toast('Distancia estimada: el servicio de rutas no respondió.','error')}catch(e){if(serial===panelTripSerial)toast(e.message,'error')}};
renderTripAdmin=function(c){panelRouteReady=false;panelTripSerial++;tripKm=0;tripDestMarker=null;tripRouteLayer=null;panelBaseTrip(c);if(!panelAccess.owner){document.getElementById('useRate').disabled=true;document.getElementById('useRate').title='Solo el propietario guarda la tarifa';}c.insertAdjacentHTML('beforeend',`<div class="section-card"><h3>Registrar viaje realizado</h3><div class="admin-grid two">${panelField('panelTripCustomer','Cliente')}${panelField('panelTripReference','Folio de pedido')}${panelField('panelTripAmount','Importe cobrado por el viaje',0,'number')}${panelField('panelTripMaterials','Productos cobrados',0,'number')}${panelField('panelTripTip','Propina del repartidor',0,'number')}</div><div class="field"><label>¿Quién recibió el cobro?</label><select id="panelTripCollector" class="select"><option value="worker">Repartidor</option><option value="business">Negocio</option></select></div><div class="field"><label>Observaciones</label><textarea class="textarea" id="panelTripNotes"></textarea></div>${panelButton('panelTripRegister','Registrar viaje',UI.save)}<p class="small muted">La comisión se calcula al guardar. Los viajes anteriores conservan su desglose.</p></div>`);document.getElementById('panelTripRegister').onclick=e=>panelRun(e.currentTarget,async()=>{if(!panelRouteReady)throw Error('Calcula primero una ruta válida en el mapa.');const customer=document.getElementById('panelTripCustomer').value.trim();if(!customer)throw Error('Escribe el cliente.');const amount=Number(document.getElementById('panelTripAmount').value),materials=Number(document.getElementById('panelTripMaterials').value),tip=Number(document.getElementById('panelTripTip').value);if([amount,materials,tip].some(n=>!Number.isFinite(n)||n<0))throw Error('Los importes deben ser positivos o cero.');await panelCall('trip_save',{id:crypto.randomUUID(),customer,reference:document.getElementById('panelTripReference').value.trim(),origin:state.config.origin,destination:{address:document.getElementById('tripDestination').value,lat:tripDestMarker.getLatLng().lat,lng:tripDestMarker.getLatLng().lng},distance:tripKm,amount,materials,tip,collector:document.getElementById('panelTripCollector').value,notes:document.getElementById('panelTripNotes').value});renderAdminPane('history')},'Viaje registrado.')};
async function panelHistory(c,epoch){c.innerHTML=`<div class="section-card"><h3>Viajes realizados</h3><div class="admin-grid two">${panelField('panelFrom','Desde','','date')}${panelField('panelTo','Hasta','','date')}</div>${panelButton('panelHistoryFilter','Consultar',UI.search,'secondary')}<div class="notice" id="panelHistoryTotal" style="margin-top:12px"></div><div id="panelHistoryList"></div></div>`;async function load(){const trips=await panelCall('trips',{from:document.getElementById('panelFrom').value,to:document.getElementById('panelTo').value});if(epoch!==panelEpoch)return;document.getElementById('panelHistoryTotal').textContent=`${trips.length} viajes · ${trips.reduce((a,t)=>a+Number(t.data.distance),0).toFixed(2)} km · Cobrado: ${money(trips.reduce((a,t)=>a+Number(t.data.total),0))} · Hasta 500 registros`;document.getElementById('panelHistoryList').innerHTML=trips.length?trips.map(t=>{const d=t.data;return `<article class="section-card"><strong>${esc(d.customer)} · ${esc(d.reference||'')}</strong><p class="small muted">${esc(new Date(t.created_at).toLocaleString('es-MX'))} · ${esc(d.operator||t.created_by)}</p><p>Salida: ${esc(d.origin?.address||'')}<br>Destino: ${esc(d.destination?.address||'')}</p>${panelSettlement(d)}<p class="small">${esc(d.notes||'')}</p><p>${d.liquidated?'Liquidación confirmada':'Liquidación pendiente'}</p>${panelAccess.owner?`<button class="btn secondary" data-panel-settle="${esc(t.id)}" data-state="${d.liquidated?'false':'true'}">${UI.check}<span>${d.liquidated?'Reabrir liquidación':'Confirmar liquidación'}</span></button>`:''}</article>`}).join(''):'<p>No hay viajes en este periodo.</p>';c.querySelectorAll('[data-panel-settle]').forEach(b=>b.onclick=()=>panelRun(b,async()=>{await panelCall('settle',{id:b.dataset.panelSettle,done:b.dataset.state==='true'});await load()},'Liquidación actualizada.'))}document.getElementById('panelHistoryFilter').onclick=e=>panelRun(e.currentTarget,load);await load()}
function panelSettlement(d){return `<div class="ticket-row"><span>Viaje</span><strong>${money(d.amount)}</strong></div><div class="ticket-row"><span>Productos íntegros para el negocio</span><strong>${money(d.materials)}</strong></div><div class="ticket-row"><span>Comisión del negocio</span><strong>${money(d.commission)}</strong></div><div class="ticket-row"><span>Propina del repartidor</span><strong>${money(d.tip)}</strong></div><div class="ticket-row total"><span>Ingreso del repartidor</span><strong>${money(d.worker_income)}</strong></div><div class="notice">${d.collector==='business'?'El negocio debe pagar al repartidor: '+money(Number(d.amount)-Number(d.commission)):'El repartidor debe entregar al negocio: '+money(Number(d.materials)+Number(d.commission))}</div>`}
async function panelCommissions(c,epoch){const rule=await panelCall('commission_get');if(epoch!==panelEpoch)return;c.innerHTML=`<div class="section-card"><h3>Comisión del negocio sobre el viaje</h3><div class="notice">La comisión solo se aplica al importe del viaje. Los productos se entregan íntegros al negocio; la propina completa es del repartidor.</div><div class="admin-grid two"><div class="field"><label>Modalidad</label><select id="panelCommissionMode" class="select"><option value="percent">Porcentaje del viaje</option><option value="fixed">Cuota fija por viaje</option></select></div>${panelField('panelCommissionValue','Porcentaje o cuota',rule.value||0,'number')}</div>${panelButton('panelSaveCommission','Guardar comisión general')}<p class="small muted">Los viajes anteriores conservan su cálculo. Una cuota fija se limita al importe del viaje.</p></div><div id="panelCommissionHistory"></div>`;document.getElementById('panelCommissionMode').value=rule.mode||'percent';document.getElementById('panelSaveCommission').onclick=e=>panelRun(e.currentTarget,async()=>{const mode=document.getElementById('panelCommissionMode').value,value=Number(document.getElementById('panelCommissionValue').value);if(!Number.isFinite(value)||value<0||mode==='percent'&&value>100)throw Error('Captura una comisión válida.');await panelCall('commission_save',{mode,value})},'Comisión guardada para próximos viajes.');const history=document.getElementById('panelCommissionHistory');await panelHistory(history,epoch)}
async function panelUsers(c,epoch){const users=await panelCall('staff_list');if(epoch!==panelEpoch)return;c.innerHTML=`<div class="section-card"><h3>Usuarios y permisos</h3><p class="small">Cada colaborador inicia sesión con su propio correo y contraseña. Primero crea su cuenta en Supabase Authentication; aquí asigna los módulos a su ID de usuario.</p><div class="admin-grid two">${panelField('panelStaffId','ID del usuario (UUID)')}${panelField('panelStaffName','Nombre del colaborador')}</div><div class="permission-grid">${adminTabs.filter(t=>['history','trip','deliveries','ticket','customers'].includes(t[0])).map(([id,label])=>`<label class="permission-option"><input type="checkbox" data-panel-module="${id}"><span>${esc(label)}</span></label>`).join('')}</div><p class="small muted">Productos, Personalización, Negocio e Integraciones requieren rol propietario en esta adaptación. Los permisos de datos se verifican en el servidor.</p>${panelButton('panelStaffSave','Guardar permisos')} ${panelButton('panelStaffClear','Limpiar',UI.close,'ghost')}</div><div class="section-card"><h3>Colaboradores</h3>${users.map(u=>`<div class="product-admin"><div><strong>${esc(u.data.name||u.id)}</strong><p class="small">${esc(u.id)} · ${u.data.enabled===false?'Inactivo':'Activo'}<br>${esc((u.data.modules||[]).join(', '))}</p></div><div class="row"><button class="icon-btn" data-panel-staff-edit="${esc(u.id)}" aria-label="Editar">${UI.edit}</button><button class="icon-btn" data-panel-staff-remove="${esc(u.id)}" aria-label="Revocar permisos">${UI.trash}</button></div></div>`).join('')||'<p>No hay colaboradores registrados.</p>'}</div>`;const clear=()=>{document.getElementById('panelStaffId').value='';document.getElementById('panelStaffName').value='';c.querySelectorAll('[data-panel-module]').forEach(x=>x.checked=false)};document.getElementById('panelStaffClear').onclick=clear;document.getElementById('panelStaffSave').onclick=e=>panelRun(e.currentTarget,async()=>{const id=document.getElementById('panelStaffId').value.trim();if(!/^[0-9a-f-]{36}$/i.test(id))throw Error('Escribe un UUID válido.');await panelCall('staff_save',{id,name:document.getElementById('panelStaffName').value.trim(),modules:[...c.querySelectorAll('[data-panel-module]:checked')].map(x=>x.dataset.panelModule)});renderAdminPane('users')},'Permisos guardados.');c.querySelectorAll('[data-panel-staff-edit]').forEach(b=>b.onclick=()=>{const u=users.find(x=>x.id===b.dataset.panelStaffEdit);document.getElementById('panelStaffId').value=u.id;document.getElementById('panelStaffName').value=u.data.name;c.querySelectorAll('[data-panel-module]').forEach(x=>x.checked=u.data.modules.includes(x.dataset.panelModule));c.scrollTop=0});c.querySelectorAll('[data-panel-staff-remove]').forEach(b=>b.onclick=()=>{if(confirm('¿Revocar todos los permisos de este colaborador?'))panelRun(b,async()=>{await panelCall('staff_remove',{id:b.dataset.panelStaffRemove});renderAdminPane('users')},'Permisos revocados.')})}
async function panelDeliveries(c,epoch){const rows=await panelCall('deliveries');if(epoch!==panelEpoch)return;c.innerHTML=`<div class="section-card"><h3>Entregas y seguimiento</h3><div class="toolbar">${panelField('panelDeliverySearch','Buscar folio o cliente')}${panelButton('panelDeliveryRefresh','Actualizar',UI.refresh,'secondary')}</div><div id="panelDeliveryList"></div></div>`;const draw=()=>{const term=document.getElementById('panelDeliverySearch').value.toLowerCase();document.getElementById('panelDeliveryList').innerHTML=rows.filter(o=>(String(o.folio)+' '+o.customer_name).toLowerCase().includes(term)).map(o=>`<article class="section-card"><strong>Pedido ${esc(o.folio)} · ${esc(o.customer_name||'')}</strong><p>${esc(o.delivery_address||'Recoger en sitio')}</p><p>${money(o.total)} · ${esc(o.delivery?.stage||'Disponible')} · ${esc(o.delivery?.operator||'Sin asignar')}</p><div class="toolbar"><button class="btn secondary" data-panel-delivery="${esc(o.id)}" data-action="start">${UI.map}<span>Tomar viaje</span></button><button class="btn" data-panel-delivery="${esc(o.id)}" data-action="finish">${UI.check}<span>Confirmar entrega con GPS</span></button></div>${o.delivery?.location?`<a href="https://www.openstreetmap.org/?mlat=${Number(o.delivery.location.lat)}&mlon=${Number(o.delivery.location.lng)}" target="_blank" rel="noopener">Ver última ubicación registrada</a>`:''}</article>`).join('')||'<p>No hay entregas pagadas que coincidan.</p>';c.querySelectorAll('[data-panel-delivery]').forEach(b=>b.onclick=()=>panelRun(b,async()=>{const p=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,timeout:20000,maximumAge:0}));await panelCall('delivery_action',{id:b.dataset.panelDelivery,action:b.dataset.action,location:{lat:p.coords.latitude,lng:p.coords.longitude,accuracy:p.coords.accuracy,captured_at:new Date(p.timestamp).toISOString()}});renderAdminPane('deliveries')},'Entrega actualizada.'))};document.getElementById('panelDeliverySearch').oninput=draw;document.getElementById('panelDeliveryRefresh').onclick=()=>renderAdminPane('deliveries');draw()}
async function panelCustomers(c,epoch){const result=await panelCall('customers');if(epoch!==panelEpoch)return;c.innerHTML=`<div class="section-card"><h3>Clientes y bloqueos</h3>${panelField('panelCustomerSearch','Buscar por nombre o teléfono')}<p class="small muted">Se agrupan por teléfono de pedido. El bloqueo se aplica al registrar pedidos mediante submit_order, después de instalar el SQL adjunto.</p><div id="panelCustomerList"></div></div>`;const draw=()=>{const q=document.getElementById('panelCustomerSearch').value.toLowerCase();document.getElementById('panelCustomerList').innerHTML=result.filter(u=>(u.name+' '+u.phone).toLowerCase().includes(q)).map(u=>`<article class="section-card"><strong>${esc(u.name||'Sin nombre')}</strong><p>${esc(u.phone)} · ${u.count} pedidos · ${money(u.total)}</p><p>${u.blocked?'Bloqueado: '+esc(u.reason||''):'Activo'}</p><button class="btn ${u.blocked?'secondary':'danger'}" data-panel-customer="${esc(u.phone)}" data-block="${!u.blocked}">${UI.shield}<span>${u.blocked?'Desbloquear':'Bloquear'}</span></button></article>`).join('')||'<p>No hay clientes que coincidan.</p>';c.querySelectorAll('[data-panel-customer]').forEach(b=>b.onclick=()=>{const blocked=b.dataset.block==='true',reason=blocked?prompt('Motivo del bloqueo:'):'';if(blocked&&reason===null)return;panelRun(b,async()=>{await panelCall('customer_block',{phone:b.dataset.panelCustomer,blocked,reason});renderAdminPane('customers')},'Bloqueo actualizado.')})};document.getElementById('panelCustomerSearch').oninput=draw;draw()}
async function panelTicket(c,epoch){state.config.ticket=state.config.ticket||{title:'PEDIDO',color:'#16324f',footer:'Gracias por tu compra',image:'',width:80};const d=state.config.ticket;c.innerHTML=`<div class="section-card"><h3>Diseño de ticket</h3><div class="admin-grid two">${panelField('panelTicketTitle','Encabezado',d.title)}${panelField('panelTicketColor','Color del encabezado',d.color,'color')}${panelField('panelTicketFooter','Pie del ticket',d.footer)}<div class="field"><label>Formato</label><select class="select" id="panelTicketWidth"><option value="80">Ticket de 80 mm</option><option value="a4">Hoja A4</option></select></div></div><div class="field"><label>Imagen junto al logo</label><input id="panelTicketImage" class="input" type="file" accept="image/png,image/jpeg,image/webp"></div>${panelButton('panelTicketRemove','Quitar imagen',UI.trash,'ghost')}<div id="panelTicketPreview" class="ticket-preview"></div><div class="toolbar">${panelButton('panelTicketSave','Guardar diseño')}${panelButton('panelTicketPdf','Descargar muestra PDF',UI.download,'secondary')}</div></div>`;document.getElementById('panelTicketWidth').value=String(d.width);let image=d.image;const read=()=>({title:document.getElementById('panelTicketTitle').value.trim(),color:document.getElementById('panelTicketColor').value,footer:document.getElementById('panelTicketFooter').value,image,width:document.getElementById('panelTicketWidth').value});const preview=()=>{const t=read();document.getElementById('panelTicketPreview').innerHTML=`<div class="row" style="justify-content:space-between">${state.config.logo?`<img src="${esc(state.config.logo)}" alt="Logo">`:''}${t.image?`<img src="${esc(t.image)}" alt="Imagen de encabezado">`:''}</div><h3 style="background:${t.color};color:white;padding:12px">${esc(t.title)} #0001</h3><strong>${esc(state.config.businessName)}</strong><p>Cliente de ejemplo</p><div class="ticket-row"><span>Producto × 1</span><span>${money(100)}</span></div><div class="ticket-row total"><span>TOTAL</span><span>${money(100)}</span></div><p>${esc(t.footer)}</p>`};c.querySelectorAll('input:not([type=file]),select').forEach(i=>i.oninput=preview);document.getElementById('panelTicketImage').onchange=async e=>{try{if(e.target.files[0])image=await panelReadImage(e.target.files[0]);preview()}catch(e){toast(e.message,'error')}};document.getElementById('panelTicketRemove').onclick=()=>{image='';preview()};document.getElementById('panelTicketSave').onclick=e=>panelRun(e.currentTarget,async()=>{await panelCall('ticket_save',read());state.config.ticket=read();saveLocal()},'Diseño guardado.');document.getElementById('panelTicketPdf').onclick=e=>panelRun(e.currentTarget,async()=>{const o={folio:'MUESTRA',dateText:new Date().toLocaleString('es-MX'),customer:{name:'Cliente de ejemplo',phone:'',notes:''},delivery:{label:'Domicilio',address:'Dirección de ejemplo'},items:[{name:'Producto de ejemplo',qty:1,price:100,total:100}],subtotal:100,shipping:0,total:100,paymentTitle:'Ejemplo'};const blob=await panelBuildTicket(o,read());const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ticket-muestra.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});preview()}
async function panelBuildTicket(order,ticket){const {jsPDF}=window.jspdf,wide=ticket.width==='a4',w=wide?210:80;const rows=order.items||[],doc=new jsPDF({unit:'mm',format:wide?'a4':[80,Math.max(180,110+rows.length*13)]});const margin=wide?14:5,usable=w-margin*2;let y=8;for(const [src,x] of [[state.config.logo,margin],[ticket.image,w-margin-20]])if(src){try{doc.addImage(src,'PNG',x,y,20,20)}catch{try{doc.addImage(src,'JPEG',x,y,20,20)}catch{}}}y+=24;doc.setFillColor(ticket.color||'#16324f');doc.rect(margin,y,usable,12,'F');doc.setTextColor(255);doc.setFontSize(wide?17:13);doc.text(String(ticket.title||'PEDIDO')+' #'+String(order.folio),margin+2,y+8);y+=18;doc.setTextColor(0);doc.setFontSize(wide?11:9);function line(text){const lines=doc.splitTextToSize(String(text||''),usable);if(y+lines.length*4>doc.internal.pageSize.height-12){doc.addPage();y=10}doc.text(lines,margin,y);y+=lines.length*4+2}line(state.config.businessName);line(order.dateText||new Date(order.date).toLocaleString('es-MX'));line('Cliente: '+(order.customer?.name||''));line('Teléfono: '+(order.customer?.phone||''));line('Entrega: '+(order.delivery?.label||''));line(order.delivery?.address);doc.autoTable({startY:y,margin:{left:margin,right:margin},head:[['Producto','Cant.','Total']],body:rows.map(i=>[i.name,String(i.qty),money(i.total)]),styles:{fontSize:wide?9:8,cellPadding:2},headStyles:{fillColor:ticket.color||'#16324f'},theme:'grid'});y=doc.lastAutoTable.finalY+7;line('Subtotal: '+money(order.subtotal));line('Envío: '+money(order.shipping));doc.setFont('helvetica','bold');line('TOTAL: '+money(order.total));doc.setFont('helvetica','normal');line('Pago: '+(order.paymentTitle||''));line(order.customer?.notes);line(ticket.footer);return doc.output('blob')}
const panelOriginalPdf=buildPdf;buildPdf=async function(order){return state.config.ticket?panelBuildTicket(order,state.config.ticket):panelOriginalPdf(order)};
const panelPublicLoad=loadPublicCloudState;loadPublicCloudState=async function(){await panelPublicLoad();try{if(supabaseClient){const {data,error}=await supabaseClient.rpc('catalog_ticket');if(!error&&data&&Object.keys(data).length){state.config.ticket=data;saveLocal()}}}catch{}};
