function ticketLines(text,max){const words=String(text||'').replace(/[\r\n]+/g,' ').split(/\s+/),out=[];let line='';for(let word of words){while(word.length>max){if(line){out.push(line);line=''}out.push(word.slice(0,max));word=word.slice(max)}if((line+' '+word).trim().length>max){out.push(line);line=word}else line=(line+' '+word).trim()}if(line)out.push(line);return out}
