 if(d.showLogo&&state.config.logo||d.image){const size=Math.min(usable*.3,85);if(d.showLogo&&state.config.logo)parts.push(`<image href="${esc(state.config.logo)}" x="${margin}" y="${y}" width="${size}" height="${size}" preserveAspectRatio="xMidYMid meet"/>`);if(d.image)parts.push(`<image href="${esc(d.image)}" x="${width-margin-size}" y="${y}" width="${size}" height="${size}" preserveAspectRatio="xMidYMid meet"/>`);y+=size+10}
 const hh=d.titleSize*scale*.3528+20;rect(margin,y,usable,hh,d.layout==='band'?d.color:d.paperColor,d.layout==='outline'?d.color:'none');rect(margin,y+hh-4,usable,4,d.accentColor);
 const icon=ticketIconSvg(d.icon).replace('<svg ',`<svg x="${margin+7}" y="${y+8}" width="${hh-18}" height="${hh-18}" style="color:${d.layout==='band'?'#ffffff':d.color}" `);parts.push(icon);const start=margin+hh,title=String(d.title||'PEDIDO'),titleFont=Math.min(d.titleSize*scale*.3528,(usable-hh-5)/Math.max(1,title.length*.57));text(title,start,y+hh*.53,titleFont,d.layout==='band'?'#ffffff':d.color,'bold');y+=hh+10;block('Folio '+order.folio,d.color,true);block(state.config.businessName,d.textColor,true);block(order.dateText||new Date(order.date).toLocaleString('es-MX'),d.mutedColor);block('Cliente: '+(order.customer?.name||''));if(d.showPhone)block('Teléfono: '+(order.customer?.phone||''));if(d.showAddress){block(order.delivery?.label||'');if(order.delivery?.address)block(order.delivery.address)}if(d.showStatus)block(ticketPaymentLabel(order.paymentStatus),d.color,true);rule();
 rect(margin,y,usable,lineHeight+8,d.color);text('Detalle',margin+4,y+fs+4,fs,'#ffffff','bold');text('Importe',width-margin-4,y+fs+4,fs,'#ffffff','bold','end');y+=lineHeight+13;
 for(const [i,item]of(order.items||[]).entries()){const product=state.products.find(p=>p.id===item.id),indent=d.showItemIcons?26:0,lines=ticketLines(`${item.qty} × ${item.name}`,Math.max(10,Math.floor((usable-indent-fs*8)/(fs*.56))));const height=Math.max(lines.length*lineHeight+8,30);if(i%2===0)rect(margin,y,usable,height,d.accentColor+'18');if(d.showItemIcons)parts.push(ticketIconSvg(product?.icon||'package').replace('<svg ',`<svg x="${margin+2}" y="${y+4}" width="20" height="20" style="color:${d.color}" `));for(const[j,line]of lines.entries())text(line,margin+indent+4,y+fs+4+j*lineHeight);text(money(item.total),width-margin-4,y+fs+4,fs,d.textColor,'normal','end');y+=height+5}
