function queueCloudModule(){
 const module=activeAdmin;
 if(['business','design','trip','profile'].includes(module)){
  vibraMarkDirty();
  pendingCloudModules.set(module,deepClone(state.config));
 }
 if(module==='products')pendingCloudModules.set('products',deepClone(state.products));
}
save=function(){
 saveLocal();
 if(adminSession&&supabaseClient){
  queueCloudModule();
  clearTimeout(cloudSyncTimer);
  cloudSyncTimer=setTimeout(()=>syncAdminStateToCloud().catch(e=>toast('No se guardaron los cambios en Supabase: '+e.message,'error')),650);
 }
};
async function vibraSaveConfig(snapshot,module){
 const payload=deepClone(snapshot);
 delete payload.adminPin;
 const {error:rpcError}=await supabaseClient.rpc('catalog_config_save',{p_module:module,p_data:payload});
 if(!rpcError)return;
 if(!/could not find the function|pgrst202|42883/i.test(String(rpcError.message||'')+' '+String(rpcError.code||'')))throw rpcError;
 const {error:tableError}=await supabaseClient.from('catalog_settings').upsert({id:1,data:payload,updated_at:new Date().toISOString()},{onConflict:'id'});
 if(tableError)throw Error('RPC: '+rpcError.message+'; tabla: '+tableError.message);
}
syncAdminStateToCloud=async function(){
 if(!supabaseClient||!adminSession)throw Error('Inicia sesión para guardar en Supabase.');
 if(cloudSaving)await cloudSaving;
 if(!pendingCloudModules.size)queueCloudModule();
 const entries=[...pendingCloudModules.entries()];
 if(!entries.length)return;
 cloudSaving=(async()=>{
  for(const [module,snapshot] of entries){
   if(!panelCan(module))throw Error('No tienes permisos para guardar el módulo '+module);
   if(module==='products'){
    const rows=snapshot.filter(p=>/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(p.id))).map((p,i)=>productRow(p,i));
    if(rows.some(p=>!Number.isFinite(p.price)||p.price<0||!Number.isFinite(p.stock)||p.stock<0))throw Error('Precio o existencias inválidos.');
    if(rows.length){const {error}=await supabaseClient.from('products').upsert(rows,{onConflict:'id'});if(error)throw error}
    const keep=new Set(rows.map(p=>p.id));
    const remove=[...cloudProductIds].filter(id=>!keep.has(id));
    if(remove.length){const {error}=await supabaseClient.from('products').delete().in('id',remove);if(error)throw error}
    cloudProductIds=keep;
   }else{
    await vibraSaveConfig(deepClone(state.config),module);
   }
   if(pendingCloudModules.get(module)===snapshot||JSON.stringify(pendingCloudModules.get(module))===JSON.stringify(snapshot))pendingCloudModules.delete(module);
  }
  if(![...pendingCloudModules.keys()].some(x=>x!=='products') && entries.some(([m])=>m!=='products'))vibraAckConfig();
 })();
 try{await cloudSaving}finally{cloudSaving=null}
};
